"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Headless document surface. The library never rasterizes PDFs itself — that is
 * the heaviest, most opinionated dependency. Instead a viewer renders a
 * `DocumentPage` for each page, given a page-image URL (which Retab's
 * preprocessing serves) plus the page's pixel size. Normalized overlays (bbox,
 * page highlights) are composed as children using percentage coordinates, so
 * they stay correct at any rendered size.
 *
 * Consumers who need live PDF rasterization can swap in a pdfjs-backed surface
 * that satisfies the same `children`-over-a-relatively-positioned-box contract.
 */

export interface DocumentPageProps {
  /** URL of the rendered page image (PNG/JPEG/WebP). */
  src?: string
  /** Intrinsic page size, used to reserve aspect ratio before the image loads. */
  width?: number
  height?: number
  alt?: string
  /** Overlay content positioned with percentage coordinates. */
  children?: React.ReactNode
  className?: string
  onLoadSize?: (size: { width: number; height: number }) => void
}

export function DocumentPage({
  src,
  width,
  height,
  alt = "Document page",
  children,
  className,
  onLoadSize,
}: DocumentPageProps) {
  const aspectRatio =
    width && height ? `${width} / ${height}` : undefined

  return (
    <div
      data-slot="document-page"
      className={cn(
        "relative overflow-hidden rounded-md border bg-muted",
        className
      )}
      style={{ aspectRatio }}
    >
      {src ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt={alt}
          className="block h-full w-full object-contain"
          onLoad={(e) => {
            const img = e.currentTarget
            onLoadSize?.({
              width: img.naturalWidth,
              height: img.naturalHeight,
            })
          }}
        />
      ) : (
        <div className="flex h-full min-h-32 items-center justify-center text-xs text-muted-foreground">
          No page image
        </div>
      )}
      {children}
    </div>
  )
}

export interface DocumentSurfaceProps {
  /** URL of the source document. */
  url?: string
  mimeType?: string
  title?: string
  className?: string
}

/**
 * Whole-document preview for the simple case (no per-page overlays): images
 * render inline, PDFs embed in an iframe, everything else shows a fallback.
 */
export function DocumentSurface({
  url,
  mimeType,
  title = "Document",
  className,
}: DocumentSurfaceProps) {
  if (!url) {
    return (
      <div
        data-slot="document-surface"
        className={cn(
          "flex min-h-32 items-center justify-center rounded-md border bg-muted text-xs text-muted-foreground",
          className
        )}
      >
        No document
      </div>
    )
  }

  const isImage = mimeType?.startsWith("image/")
  const isPdf = mimeType === "application/pdf"

  return (
    <div
      data-slot="document-surface"
      className={cn("overflow-hidden rounded-md border bg-muted", className)}
    >
      {isImage ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img src={url} alt={title} className="block h-full w-full object-contain" />
      ) : isPdf ? (
        <iframe src={url} title={title} className="h-full w-full" />
      ) : (
        <div className="flex h-full min-h-32 items-center justify-center p-4 text-center text-xs text-muted-foreground">
          <a
            href={url}
            target="_blank"
            rel="noreferrer"
            className="underline underline-offset-4"
          >
            Open {title}
          </a>
        </div>
      )}
    </div>
  )
}
